<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth();$admin=false;require ROOT.'/includes/panel.php';?><h1>Meus pedidos.</h1><p class="muted">A confirmação de pagamento é feita pela equipe após conferência. Acompanhe aqui sua proposta e entrega.</p><div class="table-wrap"><table><tr><th>Pedido</th><th>Produto / domínio</th><th>Valor proposto</th><th>Status</th><th>Atualizado</th></tr><?php foreach(rows('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC',[$u['id']]) as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['product_name'])?><br><small><?=e($o['domain'])?></small></td><td><?=e(money($o['amount']))?></td><td><?=e(['requested'=>'Solicitado','quoted'=>'Proposta disponível','paid'=>'Pagamento confirmado','delivered'=>'Entregue','cancelled'=>'Cancelado'][$o['status']]??$o['status'])?></td><td><?=e(datebr($o['updated_at']))?></td></tr><?php endforeach;?></table></div><?php require ROOT.'/includes/endpanel.php';?>
